import os, pty, sys, select, subprocess, time
def run(cwd, args, inputs, wait=0.4):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd)
        os.execv('/workspace/executable', ['zk']+args)
    out = b''
    for inp in inputs + [None]:
        t0=time.time()
        while time.time()-t0 < wait:
            r,_,_ = select.select([fd],[],[],0.1)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: d=b''
                if not d: break
                out += d
                t0=time.time()
        if inp is not None:
            try: os.write(fd, inp)
            except OSError: pass
    try:
        while True:
            r,_,_=select.select([fd],[],[],0.5)
            if not r: break
            d=os.read(fd,65536)
            if not d: break
            out+=d
    except OSError: pass
    os.waitpid(pid,0)
    return out
if __name__=='__main__':
    import shutil
    cwd=sys.argv[1]; 
    args=[]; inputs=[]
    mode='a'
    for a in sys.argv[2:]:
        if a=='--IN': mode='i'; continue
        if mode=='a': args.append(a)
        else: inputs.append(a.encode().decode('unicode_escape').encode())
    sys.stdout.write(run(cwd,args,inputs).decode('utf8','replace'))
