// Package cli implements the command line grammar: flag/argument declarations,
// parsing and the help renderer.
package cli

// Kind describes how a flag consumes its value.
type Kind int

const (
	// KBool is a flag without a value.
	KBool Kind = iota
	// KString takes a single string value.
	KString
	// KInt takes a single integer value.
	KInt
	// KList takes a comma separated list of strings.
	KList
)

// Flag declares a single command line flag.
type Flag struct {
	Long        string
	Short       byte // 0 when the flag has no short form
	Kind        Kind
	Placeholder string
	Help        string
	Group       string
	Hidden      bool
	Required    bool
	Enum        []string
	// Default is only used to render the placeholder, the way kong does it: when
	// no explicit placeholder is given the quoted default value is displayed.
	Default    string
	HasDefault bool
}

// Arg declares a positional argument.
type Arg struct {
	// Name is rendered verbatim in the help, brackets included.
	Name string
	Help string
	// Variadic arguments swallow every remaining positional.
	Variadic bool
}

// Command declares a command or sub-command.
type Command struct {
	Name string
	// Help is the one line summary shown in the parent's command list.
	Help string
	// Detail is an extra paragraph printed below Help in the command's own help.
	Detail string
	Args   []Arg
	Flags  []Flag
	Subs   []*Command
	// Default names the sub-command run when none is given.
	Default string
	// Group and GroupDetail place the command in a titled section of the root
	// command list.
	Group       string
	GroupDetail string
	Hidden      bool
}

const (
	groupFormatting = "Formatting"
	groupFiltering  = "Filtering"
	groupSorting    = "Sorting"
)

// globalFlags are attached to every command.
func globalFlags() []Flag {
	return []Flag{
		{Long: "help", Short: 'h', Kind: KBool, Help: "Show context-sensitive help."},
		{Long: "notebook-dir", Kind: KString, Placeholder: "PATH",
			Help: "Turn off notebook auto-discovery and set manually the notebook where commands are run."},
		{Long: "working-dir", Short: 'W', Kind: KString, Placeholder: "PATH",
			Help: "Run as if zk was started in <PATH> instead of the current working directory."},
		{Long: "no-input", Kind: KBool, Help: "Never prompt or ask for confirmation."},
		{Long: "debug", Kind: KBool, Hidden: true},
		{Long: "debug-style", Kind: KBool, Hidden: true},
	}
}

// filteringFlags are shared by list, edit and graph.
func filteringFlags() []Flag {
	return []Flag{
		{Long: "interactive", Short: 'i', Kind: KBool, Group: groupFiltering,
			Help: "Select notes interactively with fzf."},
		{Long: "limit", Short: 'n', Kind: KInt, Placeholder: "COUNT", Group: groupFiltering,
			Help: "Limit the number of notes found."},
		{Long: "match", Short: 'm', Kind: KList, Placeholder: "QUERY", Group: groupFiltering,
			Help: "Terms to search for in the notes."},
		{Long: "match-strategy", Short: 'M', Kind: KString, Placeholder: "STRATEGY", Group: groupFiltering,
			Help: "Text matching strategy among: fts, re, exact.", Default: "fts", HasDefault: true},
		{Long: "exclude", Short: 'x', Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Ignore notes matching the given path, including its descendants."},
		{Long: "tag", Short: 't', Kind: KList, Placeholder: "TAG", Group: groupFiltering,
			Help: "Find notes tagged with the given tags."},
		{Long: "mention", Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes mentioning the title of the given ones."},
		{Long: "mentioned-by", Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes whose title is mentioned in the given ones."},
		{Long: "link-to", Short: 'l', Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes which are linking to the given ones."},
		{Long: "no-link-to", Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes which are not linking to the given notes."},
		{Long: "linked-by", Short: 'L', Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes which are linked by the given ones."},
		{Long: "no-linked-by", Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes which are not linked by the given ones."},
		{Long: "orphan", Kind: KBool, Group: groupFiltering,
			Help: "Find notes which are not linked by any other note."},
		{Long: "tagless", Kind: KBool, Group: groupFiltering,
			Help: "Find notes which have no tags."},
		{Long: "missing-backlink", Kind: KBool, Group: groupFiltering,
			Help: "Find notes with at least one missing backlink."},
		{Long: "related", Kind: KList, Placeholder: "PATH", Group: groupFiltering,
			Help: "Find notes which might be related to the given ones."},
		{Long: "max-distance", Kind: KInt, Placeholder: "COUNT", Group: groupFiltering,
			Help: "Maximum distance between two linked notes."},
		{Long: "recursive", Short: 'r', Kind: KBool, Group: groupFiltering,
			Help: "Follow links recursively."},
		{Long: "created", Kind: KString, Placeholder: "DATE", Group: groupFiltering},
		{Long: "created-before", Kind: KString, Placeholder: "DATE", Group: groupFiltering,
			Help: "Find notes created before the given date."},
		{Long: "created-after", Kind: KString, Placeholder: "DATE", Group: groupFiltering,
			Help: "Find notes created after the given date."},
		{Long: "modified", Kind: KString, Placeholder: "DATE", Group: groupFiltering,
			Help: "Find notes modified on the given date."},
		{Long: "modified-before", Kind: KString, Placeholder: "DATE", Group: groupFiltering,
			Help: "Find notes modified before the given date."},
		{Long: "modified-after", Kind: KString, Placeholder: "DATE", Group: groupFiltering,
			Help: "Find notes modified after the given date."},
	}
}

func sortingFlag(what string) Flag {
	return Flag{Long: "sort", Short: 's', Kind: KList, Placeholder: "TERM", Group: groupSorting,
		Help: "Order the " + what + " by the given criterion."}
}

// deprecatedExactMatch is hidden but still recognised; it always errors out.
func deprecatedExactMatch() Flag {
	return Flag{Long: "exact-match", Short: 'e', Kind: KBool, Hidden: true}
}

func filterArgs() []Arg {
	return []Arg{{Name: "[<path> ...]", Variadic: true,
		Help: "Find notes matching the given path, including its descendants."}}
}

// listingFlags are the formatting flags shared by `list` and `tag list`.
func listingFlags(what, formats string) []Flag {
	return []Flag{
		{Long: "format", Short: 'f', Kind: KString, Placeholder: "TEMPLATE", Group: groupFormatting,
			Help: "Pretty print the list using a custom template or one of the predefined formats: " + formats + "."},
		{Long: "header", Kind: KString, Group: groupFormatting,
			Help: "Arbitrary text printed at the start of the list."},
		{Long: "footer", Kind: KString, Group: groupFormatting, Default: `\n`, HasDefault: true,
			Help: "Arbitrary text printed at the end of the list."},
		{Long: "delimiter", Short: 'd', Kind: KString, Group: groupFormatting, Default: "\n", HasDefault: true,
			Help: "Print " + what + " delimited by the given separator."},
		{Long: "delimiter0", Short: '0', Kind: KBool, Group: groupFormatting,
			Help: "Print " + what + " delimited by ASCII NUL characters. This is useful when used in conjunction with `xargs -0`."},
		{Long: "no-pager", Short: 'P', Kind: KBool, Group: groupFormatting,
			Help: "Do not pipe output into a pager."},
		{Long: "quiet", Short: 'q', Kind: KBool, Group: groupFormatting,
			Help: "Do not print the total number of " + what + " found."},
	}
}

// Root builds the complete command tree.
func Root() *Command {
	const notebookGroup = "NOTEBOOK"
	const notebookDetail = "A notebook is a directory containing a collection of notes"
	const notesGroup = "NOTES"
	const notesDetail = "Edit or browse your notes"

	initCmd := &Command{
		Name: "init", Help: "Create a new notebook in the given directory.",
		Group: notebookGroup, GroupDetail: notebookDetail,
		Args: []Arg{{Name: "[<directory>]", Help: "Directory containing the notebook."}},
	}
	indexCmd := &Command{
		Name: "index", Help: "Index the notes to be searchable.",
		Detail: "You usually do not need to run `zk index` manually, as notes are indexed automatically when needed.",
		Group:  notebookGroup, GroupDetail: notebookDetail,
		Flags: []Flag{
			{Long: "force", Short: 'f', Kind: KBool, Help: "Force indexing all the notes."},
			{Long: "verbose", Short: 'v', Kind: KBool, Help: "Print detailed information about the indexing process."},
			{Long: "quiet", Short: 'q', Kind: KBool, Help: "Do not print statistics nor progress."},
		},
	}
	newCmd := &Command{
		Name: "new", Help: "Create a new note in the given notebook directory.",
		Group: notesGroup, GroupDetail: notesDetail,
		Args:  []Arg{{Name: "[<directory>]", Help: "Directory in which to create the note."}},
		Flags: []Flag{
			{Long: "interactive", Short: 'i', Kind: KBool, Help: "Read contents from standard input."},
			{Long: "title", Short: 't', Kind: KString, Placeholder: "TITLE", Help: "Title of the new note."},
			{Long: "date", Kind: KString, Placeholder: "DATE", Help: "Set the current date."},
			{Long: "group", Short: 'g', Kind: KString, Placeholder: "NAME",
				Help: "Name of the config group this note belongs to. Takes precedence over the config of the directory."},
			{Long: "extra", Kind: KList, Placeholder: "KEY=VALUE", Help: "Extra variables passed to the templates."},
			{Long: "template", Kind: KString, Placeholder: "PATH", Help: "Custom template used to render the note."},
			{Long: "print-path", Short: 'p', Kind: KBool, Help: "Print the path of the created note instead of editing it."},
			{Long: "dry-run", Short: 'n', Kind: KBool,
				Help: "Don't actually create the note. Instead, prints its content on stdout and the generated path on stderr."},
			{Long: "id", Kind: KString, Placeholder: "ID", Help: "Skip id generation and use provided value."},
		},
	}
	listCmd := &Command{
		Name: "list", Help: "List notes matching the given criteria.",
		Group: notesGroup, GroupDetail: notesDetail,
		Args:  filterArgs(),
	}
	listCmd.Flags = append(listCmd.Flags, listingFlags("notes", "oneline, short, medium, long, full, json, jsonl")...)
	listCmd.Flags = append(listCmd.Flags, filteringFlags()...)
	listCmd.Flags = append(listCmd.Flags, sortingFlag("notes"), deprecatedExactMatch())

	graphCmd := &Command{
		Name: "graph", Help: "Produce a graph of the notes matching the given criteria.",
		Group: notesGroup, GroupDetail: notesDetail,
		Args:  filterArgs(),
		Flags: []Flag{
			{Long: "format", Short: 'f', Kind: KString, Group: groupFormatting, Required: true,
				Help: "Format of the graph among: json."},
			{Long: "quiet", Short: 'q', Kind: KBool, Group: groupFormatting,
				Help: "Do not print the total number of notes found."},
		},
	}
	graphCmd.Flags = append(graphCmd.Flags, filteringFlags()...)
	graphCmd.Flags = append(graphCmd.Flags, sortingFlag("notes"), deprecatedExactMatch())

	editCmd := &Command{
		Name: "edit", Help: "Edit notes matching the given criteria.",
		Group: notesGroup, GroupDetail: notesDetail,
		Args:  filterArgs(),
		Flags: []Flag{
			{Long: "force", Short: 'f', Kind: KBool,
				Help: "Do not confirm before editing many notes at the same time."},
		},
	}
	editCmd.Flags = append(editCmd.Flags, filteringFlags()...)
	editCmd.Flags = append(editCmd.Flags, sortingFlag("notes"), deprecatedExactMatch())

	tagList := &Command{Name: "list", Help: "List all the note tags."}
	tagList.Flags = append(tagList.Flags, listingFlags("tags", "name, full, json, jsonl")...)
	tagList.Flags = append(tagList.Flags, sortingFlag("tags"))
	tagCmd := &Command{
		Name: "tag", Help: "Manage the note tags.",
		Group: notesGroup, GroupDetail: notesDetail,
		Subs:  []*Command{tagList}, Default: "list",
	}

	lspCmd := &Command{Name: "lsp", Hidden: true}

	root := &Command{
		Name: "zk",
		Subs: []*Command{initCmd, indexCmd, newCmd, listCmd, graphCmd, editCmd, tagCmd, lspCmd},
	}
	attachGlobals(root)
	return root
}

// attachGlobals prepends the global flags to every command of the tree.
func attachGlobals(c *Command) {
	c.Flags = append(globalFlags(), c.Flags...)
	for _, sub := range c.Subs {
		attachGlobals(sub)
	}
}

